  "<div class=\"buttons\"><button class=\"btn primary\" data-open=\"gas\">{}Open script.google.com</button></div>": "<div class=\"buttons\"><button class=\"btn primary\" data-open=\"gas\">{}Открыть script.google.com</button></div>",
  "<div class=\"label\">Your secret key</div> <div class=\"input-row\"><input id=\"wz-key\" class=\"mono\" value=\"{}\" spellcheck=\"false\" autocomplete=\"off\" aria-label=\"Your secret key\"><button class=\"mini big\" type=\"button\" id=\"wz-newkey\" title=\"Make a new key\">{}</button></div> <div class=\"code\"><pre id=\"wz-code\">{}</pre><button class=\"btn\" type=\"button\" id=\"wz-copy\">{}Copy code</button></div>": "<div class=\"label\">Ваш секретный ключ</div> <div class=\"input-row\"><input id=\"wz-key\" class=\"mono\" value=\"{}\" spellcheck=\"false\" autocomplete=\"off\" aria-label=\"Ваш секретный ключ\"><button class=\"mini big\" type=\"button\" id=\"wz-newkey\" title=\"Создать новый ключ\">{}</button></div> <div class=\"code\"><pre id=\"wz-code\">{}</pre><button class=\"btn\" type=\"button\" id=\"wz-copy\">{}Скопировать код</button></div>",
